struct B1 { int b1; };
struct B2 { double b2; };

struct Derived : B1, B2 {
    char d;

    // Must initialize bases explicitly in Custom Copy Constructor
    Derived(const Derived& other)
        : B1(other),
          B2(other),
          d(other.d)
    {}

    // Must call base assignments explicitly in Custom Assignment Op
    Derived& operator=(const Derived& other) {
        B1::operator=(other);
        B2::operator=(other);
        d = other.d;
        return *this;
    }
};
